const host=n=>`https://${n}.aimersociety.com/`;
const subjects=[
['Maths','From numbers to new worlds','Science','maths',148,477],['Physics','Unveil the laws of reality','Science','physics',429,477],['Biology','Life through data and models','Science','biology',694,477],['Chemistry','Build. Simulate. Discover.','Science','chemistry.iq-labs',969,477],['Deep Learning','Neural nets for a smarter world','Computing','ml',1240,477],['Machine Learning Algorithms','Data to intelligence','Computing','ml',1517,477],['Computer Organization','From logic gates to intelligence','Computing','os',150,610],['AI Algorithms','Build intelligent solutions','Computing','ml',431,610],['DAA','Design. Analyze. Optimize.','Computing','iq-labs',698,610],['Data Structures','Organize. Access. Solve.','Computing','dbms',967,610],['Computer Vision','See. Understand. Create.','Computing','ml',1240,610],['VLSI','Design tomorrow’s chips','Engineering','digital',1519,610],['Digital Logic','Logic. Design. Innovate.','Engineering','digital',151,733],['Electronics Labs','From circuits to real-world impact','Engineering','electronics-lab',430,733],['IQ Labs','Think. Experiment. Innovate.','Labs','iq-labs',699,733],['NLP','Language for a better tomorrow','Computing','ml',965,733],['Cryptography','Secure ideas. Safer tomorrow.','Computing','iq-labs',1240,733],['Probability & Statistics','Find patterns. Predict possibilities.','Science','maths',1519,733],['Business Analytics','Turn data into decisions','Labs','businessanalytics',1519,733],['Database Management','Explore, query, understand','Computing','dbms',967,610],['Operating Systems','Explore the foundations of computing','Computing','os',150,610]
];
let category='All';const grid=document.querySelector('#subjects-grid'),search=document.querySelector('#search');
function render(){const q=search.value.trim().toLowerCase();const found=subjects.filter(s=>(category==='All'||s[2]===category)&&`${s[0]} ${s[1]} ${s[2]}`.toLowerCase().includes(q));grid.innerHTML=found.map(s=>`<a class="card" href="${host(s[3])}" target="_blank" rel="noopener" aria-label="Open ${s[0]}"><span class="art" style="background-position:${60-s[4]}px ${40-s[5]}px" aria-hidden="true"></span><h3>${s[0]}</h3><p>${s[1]}</p><span class="arrow" aria-hidden="true">→</span></a>`).join('');document.querySelector('#empty').hidden=!!found.length;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===category);b.setAttribute('aria-pressed',String(b.dataset.filter===category))});}
search.addEventListener('input',render);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{category=b.dataset.filter;render()});document.querySelector('#clear').onclick=()=>{category='All';search.value='';render()};
const apps=[['Circuits Simulator','⚡','circuitssimulator'],['Maths App','▦','aiexplorer'],['Biology App','🧬','AIbiology'],['Chemistry App','⚗','aichemistryexplorer']];document.querySelector('#apps-grid').innerHTML=apps.map(a=>`<a class="app-card" href="https://play.google.com/store/apps/details?id=com.indianservers.${a[2]}" target="_blank" rel="noopener"><span class="app-icon" aria-hidden="true">${a[1]}</span>${a[0]}<span class="arrow" aria-hidden="true">→</span></a>`).join('');
const theme=document.querySelector('#theme');try{document.body.classList.toggle('dark',localStorage.getItem('aimers-theme')==='dark')}catch{}theme.onclick=()=>{const dark=document.body.classList.toggle('dark');theme.textContent=dark?'☾':'☼';try{localStorage.setItem('aimers-theme',dark?'dark':'light')}catch{}};
document.querySelector('#menu').onclick=()=>{const open=document.querySelector('header').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',String(open))};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{document.querySelectorAll('nav a').forEach(n=>n.classList.toggle('active',n===a));document.querySelector('header').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false')});
const dialog=document.querySelector('#dialog');document.querySelectorAll('[data-dialog]').forEach(b=>b.onclick=()=>{const community=b.dataset.dialog==='community';document.querySelector('#dialog-title').textContent=community?'Learn together. Build together.':'About AIMER Society';document.querySelector('#dialog-body').textContent=community?'Explore a shared collection of interactive labs and learning resources for students, researchers and engineers. Start your next experiment with IQ Labs.':'AIMER Society — Artificial Intelligence Medical and Engineering Researchers Society — brings science, computing and engineering together through interactive visualizations and AI-powered learning.';dialog.showModal()});document.querySelector('#close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();search.focus()}});render();
